23	        String householdId = owner.getHouseholdId();
24	        if (householdId == null) {
25	            return; // no household to key on, so no cap
26	        }
27	        Integer maxLevel = null;
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (householdId.equals(existing.getHouseholdId())) {
30	                int level = MembershipLevel.of(existing);
31	                if (maxLevel == null || level > maxLevel) {
32	                    maxLevel = level;
33	                }
34	            }
35	        }
